target.css:
:root {
  --bg-board: #1a1a2e;
  --bg-header: #e94560;
  --bg-featured: #f5a623;
  --bg-item: #ffffff;
  --bg-footer: #16213e;
  --text-title: #ffffff;
  --text-subtitle: #ffd6de;
  --text-name: #1a1a2e;
  --text-desc: #6b7280;
  --text-price: #e94560;
  --text-featured-price: #1a1a2e;
  --text-footer: #a0aec0;
  --text-hours: #f5a623;
  --badge-bg: #ffffff;
  --badge-text: #e94560;
  --border-item: #e5e7eb;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
}

.board {
  width: 420px;
  border-radius: 12px;
  overflow: hidden;
}

.cart-header {
  background-color: var(--bg-header);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
}

.cart-icon {
  font-size: 18px;
  line-height: 1;
}

.cart-title {
  flex: 1;
}

.cart-title h1 {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-title);
  line-height: 1.2;
}

.cart-subtitle {
  font-size: 10px;
  color: var(--text-subtitle);
  font-weight: 500;
}

.cart-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 2px 7px;
  border-radius: 20px;
}

.menu-grid {
  background-color: var(--bg-board);
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 8px;
}

.menu-item {
  background-color: var(--bg-item);
  border: 1.5px solid var(--border-item);
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 9px;
}

.menu-item.featured {
  background-color: var(--bg-featured);
  border-color: var(--bg-featured);
}

.item-emoji {
  font-size: 18px;
  line-height: 1;
  flex-shrink: 0;
}

.item-info {
  flex: 1;
  min-width: 0;
}

.item-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-name);
  line-height: 1.2;
}

.item-desc {
  font-size: 10px;
  color: var(--text-desc);
  line-height: 1.3;
  margin-top: 1px;
}

.menu-item.featured .item-desc {
  color: var(--text-name);
  opacity: 0.65;
}

.item-price {
  font-size: 12px;
  font-weight: 800;
  color: var(--text-price);
  flex-shrink: 0;
  white-space: nowrap;
}

.menu-item.featured .item-price {
  color: var(--text-featured-price);
}

.cart-footer {
  background-color: var(--bg-footer);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 12px;
  gap: 6px;
}

.footer-note {
  font-size: 10px;
  color: var(--text-footer);
  font-weight: 500;
}

.hours {
  font-size: 10px;
  color: var(--text-hours);
  font-weight: 700;
  letter-spacing: 0.02em;
}

